/**
 * Cloudflare Worker entry (wrangler.jsonc `main`). Wraps OpenNext's generated Worker with the API
 * edge cache Vercel's CDN provided; see `utils/api-edge-cache.ts`.
 */
// @ts-ignore -- generated by `opennextjs-cloudflare build`
import openNextWorker from "./.open-next/worker.js";
import { withApiEdgeCache } from "./utils/api-edge-cache";

// @ts-ignore -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler } from "./.open-next/worker.js";

type WorkerContext = { waitUntil(promise: Promise<unknown>): void };
type OpenNextWorker = {
  fetch(request: Request, env: unknown, ctx: WorkerContext): Promise<Response>;
};

const worker: OpenNextWorker = {
  fetch(request, env, ctx) {
    const handler = (req: Request) =>
      (openNextWorker as OpenNextWorker).fetch(req, env, ctx);
    // `caches.default` is the Workers runtime's shared cache for this location.
    const cache = (caches as unknown as { default: Cache }).default;
    return withApiEdgeCache(handler, cache, (promise) =>
      ctx.waitUntil(promise)
    )(request);
  },
};

export default worker;
